insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'alluvial-mining', 'en', 'Alluvial Mining', 'The extraction of minerals deposited by water action in riverbeds, floodplains, or ancient water channels. Gold and diamond alluvial mining is common in West Africa.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'angle-of-repose', 'en', 'Angle of Repose', 'The steepest angle at which a material — such as waste rock or soil — can be piled without sliding. Exceeding the angle of repose causes slope failures and dangerous landslides.', 'Geotechnical', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'artisanal-mining', 'en', 'Artisanal Mining', 'Small-scale, informal mining carried out by individuals or small groups using basic tools. Often unregulated, it poses significant safety and environmental risks.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'assay', 'en', 'Assay', 'A chemical analysis of ore or mineral samples to determine the content and grade of valuable metals or minerals present. Results guide mine planning and ore processing decisions.', 'Testing & Analysis', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'authorized-person', 'en', 'Authorized Person', 'A person designated by the mine manager as competent and authorized to perform specific tasks or enter specific areas of the mine site.', 'Safety & Personnel', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'aerial-tramway', 'en', 'Aerial Tramway', 'A cable-supported system used to transport ore, equipment, or personnel between different elevations on a mine site, particularly in mountainous or steep terrain.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'acid-mine-drainage', 'en', 'Acid Mine Drainage (AMD)', 'Water that becomes acidic after reacting with sulfide minerals exposed during mining. AMD is one of the most serious environmental hazards in mining and can contaminate water supplies for decades.', 'Environment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'airleg', 'en', 'Airleg', 'A pneumatic device used to support and feed a rock drill during underground drilling operations. It allows the driller to control the thrust and direction of the drill bit.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'backfill', 'en', 'Backfill', 'Material used to refill excavated areas or voids in a mine. Backfill supports the surrounding rock, controls subsidence, and can be made from waste rock, tailings, or cemented paste.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'barren-zone', 'en', 'Barren Zone', 'A section of rock within or around a mineral deposit that contains little or no economic mineral content. Barren zones must be identified and separated from ore during mining.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'bench', 'en', 'Bench', 'A horizontal ledge or step in an open pit mine. Benches are worked progressively downward and provide platforms for drilling, blasting, loading, and haulage operations.', 'Open Pit Mining', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'bench-height', 'en', 'Bench Height', 'The vertical distance between two adjacent bench levels in an open pit mine. Bench height is determined by the type of equipment used and rock conditions, and directly affects slope stability.', 'Open Pit Mining', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'blasting', 'en', 'Blasting', 'The controlled use of explosives to break rock or ore in mining operations. Requires strict safety protocols, licensed blasting personnel, exclusion zones, and formal blast notifications.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'blast-hole', 'en', 'Blast Hole', 'A hole drilled into rock in which explosives are loaded for blasting. The diameter, depth, and pattern of blast holes are engineered based on rock properties and the desired fragmentation size.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'blast-pattern', 'en', 'Blast Pattern', 'The geometric arrangement of blast holes across a face or bench, including spacing, burden, and stagger. A well-designed blast pattern ensures effective fragmentation and minimizes flyrock.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'block-caving', 'en', 'Block Caving', 'An underground mining method where a large block of ore is undercut to allow it to collapse under gravity. One of the lowest-cost underground mining methods, used for large low-grade deposits.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'borehole', 'en', 'Borehole', 'A narrow hole drilled into the ground for exploration, water supply, or geotechnical investigation. Borehole samples provide critical information about the geology and grade of a deposit.', 'Exploration', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'bund-berm', 'en', 'Bund / Berm', 'An earthen wall or embankment built at the edge of haul roads, pit crests, and dump edges to prevent vehicles from going over. Height must be at least half the wheel diameter of the largest operating vehicle.', 'Safety Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'burden', 'en', 'Burden', 'The distance between the front row of blast holes and the free face of the bench being blasted. Correct burden is critical for effective fragmentation and to prevent flyrock.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'bullion', 'en', 'Bullion', 'A bulk quantity of precious metal, typically gold or silver, that has been refined and cast into bars or ingots. Bullion is the final product of many gold mining operations.', 'Processing', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'cage', 'en', 'Cage', 'An enclosed elevator used to transport workers and materials up and down a mine shaft. Must be maintained, tested regularly, and operated by a certified hoist operator.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'cap-rock', 'en', 'Cap Rock', 'Hard rock that sits directly above an ore body or softer formation. Cap rock must be drilled and blasted before the ore below can be accessed.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'carbon-in-leach', 'en', 'Carbon-in-Leach (CIL)', 'A gold processing method where activated carbon is added to a cyanide leach slurry to simultaneously leach and adsorb gold. One of the most common gold recovery techniques.', 'Processing', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'catch-berm', 'en', 'Catch Berm', 'A wide, flat step cut into a pit wall to catch falling rock and debris, preventing material from reaching lower benches where workers and equipment are operating.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'cave-in', 'en', 'Cave-in', 'The sudden and uncontrolled collapse of the roof, walls, or floor in a mine excavation. Cave-ins are among the most deadly hazards in underground mining and require immediate evacuation.', 'Ground Hazards', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'cemented-paste-fill', 'en', 'Cemented Paste Fill', 'A mixture of tailings, water, and cement used as underground backfill. It provides strong, stable support for underground voids and prevents collapse of mined-out areas.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'chain-pillar', 'en', 'Chain Pillar', 'A long, narrow pillar of unmined ore or rock left in place between adjacent excavations to provide roof support and prevent surface subsidence in underground mines.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'chalcopyrite', 'en', 'Chalcopyrite', 'A copper-iron sulfide mineral (CuFeS2) and the most important ore of copper. Brass-yellow in color, it is commonly found in many porphyry copper and volcanogenic massive sulfide deposits.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'collar', 'en', 'Collar', 'The top or mouth of a drill hole or mine shaft. The collar must be properly cased and secured to prevent collapse and to support drilling or hoisting equipment.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'competent-person', 'en', 'Competent Person', 'A person with appropriate qualifications, training, and experience to identify hazards in the workplace and who has the authority to take immediate corrective action.', 'Safety & Personnel', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'confined-space', 'en', 'Confined Space', 'An enclosed or partially enclosed space not designed for continuous human occupancy, which has restricted entry/exit and may have hazardous atmospheres. Entry requires a permit, gas testing, and a standby person.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'contour-mining', 'en', 'Contour Mining', 'A surface mining technique used on hilly or mountainous terrain where cuts are made along the natural contour lines of the land to access coal or mineral seams.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'core-sample', 'en', 'Core Sample', 'A cylindrical sample of rock extracted during diamond drilling for geological analysis. Core samples reveal the rock type, structure, mineral content, and grade of a deposit.', 'Exploration', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'crusher', 'en', 'Crusher', 'A machine used to reduce the size of blasted rock or ore into smaller fragments for further processing. Types include jaw crushers, gyratory crushers, and cone crushers.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'cut-and-fill', 'en', 'Cut-and-Fill', 'An underground mining method where ore is extracted in horizontal slices and the void is filled with waste rock or cemented paste before the next slice is mined above.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'cyanide', 'en', 'Cyanide', 'A toxic chemical compound (sodium cyanide or potassium cyanide) used in gold and silver processing to dissolve precious metals from ore. Requires strict handling procedures, storage protocols, and spill response plans.', 'Processing', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'cut-off-grade', 'en', 'Cut-off Grade', 'The minimum grade of mineral content at which it is economically viable to mine ore rather than treat it as waste. Material below the cut-off grade is stockpiled as waste.', 'Grade Control', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'dead-ground', 'en', 'Dead Ground', 'Rock or ground that contains no ore and is economically unproductive. Identifying dead ground early prevents wasted mining effort and reduces costs.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'decline', 'en', 'Decline', 'An inclined tunnel driven underground at an angle to provide vehicle and equipment access between surface and underground workings. Also called a ramp.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'detonator', 'en', 'Detonator', 'A device used to initiate the detonation of an explosive charge. Detonators are extremely sensitive and must only be handled by licensed shot-firers following strict safety protocols.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'dewatering', 'en', 'Dewatering', 'The process of removing water from a mine to maintain safe working conditions. Methods include submersible pumps, drainage galleries, and sumps. Uncontrolled flooding is a major mine safety hazard.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'diamond-drilling', 'en', 'Diamond Drilling', 'A drilling technique using a rotating bit tipped with industrial diamonds to cut cylindrical core samples from rock. Produces high-quality geological data for resource estimation.', 'Exploration', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'dike-dyke', 'en', 'Dike / Dyke', 'A sheet of igneous rock that has intruded into existing rock formations. Dykes can affect blast patterns, slope stability, and ore distribution in a mine.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'dilution', 'en', 'Dilution', 'The unintended mixing of waste rock or low-grade material with ore during the mining process, which reduces the average grade of material sent to the processing plant.', 'Grade Control', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'dip', 'en', 'Dip', 'The angle at which a rock layer, ore body, or geological structure inclines below the horizontal surface. Understanding dip is critical for mine planning and slope stability analysis.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'dozer', 'en', 'Dozer', 'A powerful tracked machine fitted with a front blade used for pushing waste rock, leveling haul roads, and constructing berms on mine sites. One of the most common pieces of mine equipment.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'drag-line', 'en', 'Drag Line', 'A large surface mining excavator that uses a dragline bucket suspended from a long boom to scoop up and move large volumes of overburden or material.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'drift', 'en', 'Drift', 'A horizontal tunnel driven underground, usually following the strike of an ore body. Drifts provide access for development, production, and ventilation in underground mines.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'drilling', 'en', 'Drilling', 'The process of creating holes in rock for exploration, blasting, or ground support purposes. Drilling is a core activity on every mine site and requires trained operators and regular equipment maintenance.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'dump', 'en', 'Dump', 'A designated area where waste rock, overburden, or other non-ore material is permanently deposited. Dumps must be engineered for stability and managed to prevent environmental contamination.', 'Waste Management', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'dust-suppression', 'en', 'Dust Suppression', 'Measures taken to reduce the amount of harmful dust in the air on a mine site, including water spraying, chemical suppressants, and enclosed processing facilities. Critical for preventing respiratory disease.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'dynamic-load', 'en', 'Dynamic Load', 'Forces generated by moving equipment, blasting, or rock mass movement that add to the static weight on structures and ground support systems. Dynamic loads are a key design consideration in underground mines.', 'Engineering', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'earthing-grounding', 'en', 'Earthing / Grounding', 'The connection of electrical equipment to the earth to prevent electric shock. All electrical equipment on mine sites must be properly earthed and regularly tested by a qualified electrician.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'electrical-hazard', 'en', 'Electrical Hazard', 'Any risk of injury, death, or equipment damage from electricity, including exposed wiring, overhead power lines, electrical storms, and energized equipment. Common cause of serious injuries in mining.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'exclusion-zone', 'en', 'Exclusion Zone', 'A defined area around a hazard — such as a blast zone, unstable slope, or working machinery — where entry is strictly prohibited to unauthorized personnel. Must be clearly marked with signage and barriers.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'exploration', 'en', 'Exploration', 'The systematic investigation of an area to locate and evaluate mineral deposits. Includes geological mapping, soil sampling, geophysical surveys, and drilling to determine deposit size and grade.', 'Exploration', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'explosive', 'en', 'Explosive', 'A chemical compound or mixture that rapidly releases energy through detonation, used to fragment rock in mining. Explosives must be stored in licensed magazines and handled only by trained shot-firers.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'excavator', 'en', 'Excavator', 'A hydraulic machine with a boom, arm, and bucket used to dig and load material in surface and underground mines. Includes face shovels, backhoe excavators, and rope shovels.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'face', 'en', 'Face', 'The exposed working surface in a mine from which ore or waste is being actively excavated. The face is typically the highest-risk area on a mine site due to freshly exposed unstable rock and ongoing blasting.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'fall-of-ground', 'en', 'Fall of Ground (FOG)', 'The uncontrolled fall of rock, soil, or debris in a mine excavation. One of the leading causes of fatalities in mining worldwide. Prevention requires systematic scaling, ground support, and regular inspections.', 'Ground Hazards', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'fault', 'en', 'Fault', 'A fracture or zone of fractures in rock along which movement has occurred. Faults can create unstable ground conditions, unexpected water inflows, and complicate ore body interpretation.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'final-wall', 'en', 'Final Wall', 'The last pit wall slope that will remain after mining is complete. Final walls are designed for long-term stability and are not subject to further blasting or disturbance.', 'Open Pit Mining', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'fire-suppression-system', 'en', 'Fire Suppression System', 'An automatic system installed on underground equipment and in processing facilities to detect and suppress fires. Must be regularly inspected and maintained to ensure operability.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'floatation', 'en', 'Floatation', 'A mineral processing technique that uses air bubbles and chemical reagents to separate valuable mineral particles from gangue (waste rock) in a water slurry.', 'Processing', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'flyrock', 'en', 'Flyrock', 'Rock fragments propelled beyond the intended blast zone during a blasting event. Flyrock is a leading cause of blast-related injuries and fatalities. Requires accurate burden calculation and proper exclusion zones.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'footwall', 'en', 'Footwall', 'The rock mass lying beneath an inclined ore body or vein. In underground mining, the footwall forms the floor of a stope or drive following the ore body.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'free-face', 'en', 'Free Face', 'An exposed surface of rock towards which blasting energy is directed. Every effective blast requires at least one free face for material to move into during detonation.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'fugitive-dust', 'en', 'Fugitive Dust', 'Dust that escapes into the atmosphere from unpaved haul roads, blasting, crushing, stockpiles, and wind erosion on mine sites. Requires control measures to protect worker health and community air quality.', 'Environment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'gangue', 'en', 'Gangue', 'The commercially worthless rock or mineral material that surrounds or is mixed with valuable ore in a deposit. Gangue must be separated from the ore during processing.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'gas-detection', 'en', 'Gas Detection', 'The continuous or periodic monitoring of underground air for dangerous gases including carbon monoxide, methane, hydrogen sulfide, and oxygen deficiency using approved gas detectors.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'geologist', 'en', 'Geologist', 'A scientist who studies the earth''s rock formations, mineral deposits, and geological structures. Mine geologists guide drilling programs, ore body interpretation, and grade control activities.', 'Safety & Personnel', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'geotechnical', 'en', 'Geotechnical', 'The engineering discipline that studies the behavior of rock and soil under stress. In mining, geotechnical engineers design pit slopes, underground support systems, and tailings storage facilities.', 'Engineering', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'gold-room', 'en', 'Gold Room', 'A secure, restricted-access room in a gold processing plant where gold is recovered from loaded carbon, smelted into doré bars, and stored before transport. Access is strictly controlled.', 'Processing', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'grade', 'en', 'Grade', 'The concentration of a valuable mineral or metal in the ore, typically expressed as grams per tonne (g/t) for gold or percentage (%) for base metals such as copper and zinc.', 'Grade Control', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'grade-control', 'en', 'Grade Control', 'The systematic process of monitoring, sampling, and managing the quality and quantity of ore being mined to ensure it meets processing plant requirements and maximizes economic recovery.', 'Grade Control', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'grinding-mill', 'en', 'Grinding Mill', 'A large rotating drum containing steel balls or rods used to grind ore into fine particles for mineral processing. Includes ball mills, rod mills, and SAG mills.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'ground-control', 'en', 'Ground Control', 'All measures taken to maintain the stability of excavations and prevent collapse, including rock bolting, shotcrete, mesh installation, and monitoring of ground movement.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'ground-support', 'en', 'Ground Support', 'Systems installed to reinforce and stabilize the rock mass around mine excavations. Includes rock bolts, cable bolts, wire mesh, shotcrete, and timber sets.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'hangingwall', 'en', 'Hangingwall', 'The rock mass lying above an inclined ore body or vein. In underground mining, the hangingwall forms the roof of a stope. Hangingwall failures are a major cause of underground injuries.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'hardrock-mining', 'en', 'Hardrock Mining', 'Mining that involves the extraction of metals and minerals from consolidated, solid rock formations using drilling, blasting, and excavation. Contrasted with soft-rock or placer mining.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'haul-road', 'en', 'Haul Road', 'A road within the mine designed and maintained for heavy equipment and haul trucks. Must be properly graded, drained, watered for dust suppression, and have adequate berms on the outer edge.', 'Infrastructure', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'haul-truck', 'en', 'Haul Truck', 'A large off-highway truck used to transport ore and waste rock between the pit or underground workings and the processing plant or waste dump. Capacities range from 40 to over 400 tonnes.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'hazard', 'en', 'Hazard', 'Any condition, situation, substance, or practice that has the potential to cause harm, injury, illness, or death to a person, or damage to property or the environment.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'hazard-identification', 'en', 'Hazard Identification', 'The systematic process of identifying all potential hazards before commencing work, typically captured in a JSA or risk assessment. The first and most critical step in the risk management process.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'hazmat', 'en', 'HazMat', 'Hazardous materials — substances that are flammable, explosive, corrosive, oxidizing, toxic, or otherwise dangerous. Handling requires special training, appropriate PPE, and adherence to Safety Data Sheets.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'headframe', 'en', 'Headframe', 'The steel or concrete structure erected over a mine shaft to support the hoisting equipment and guide ropes. A headframe is the most recognizable symbol of an underground mine.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'high-wall', 'en', 'High Wall', 'The unexcavated rock face remaining after overburden is removed in surface mining. High walls can be hundreds of metres tall and must be monitored continuously for slope instability.', 'Open Pit Mining', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'hoisting', 'en', 'Hoisting', 'The system of equipment including the hoist, headframe, shaft, and conveyances used to move personnel, ore, and materials vertically in a mine shaft.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'hydraulic-mining', 'en', 'Hydraulic Mining', 'A mining technique using high-pressure water jets to dislodge and transport ore or overburden. Commonly used in placer gold mining and some surface operations.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'hydrostatic-pressure', 'en', 'Hydrostatic Pressure', 'The pressure exerted by a column of water underground. High hydrostatic pressure can destabilize pit walls, force water into excavations, and cause sudden inrushes — a dangerous underground hazard.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'inclinometer', 'en', 'Inclinometer', 'An instrument installed in a borehole to measure the angle of inclination of a slope or structure over time, used to detect and monitor potential slope instability in pit walls and embankments.', 'Monitoring', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'induction-training', 'en', 'Induction Training', 'Mandatory safety training provided to all new workers, contractors, and visitors before they enter a mine site. Covers site rules, emergency procedures, hazard awareness, and PPE requirements.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'infrared-sensor', 'en', 'Infrared Sensor', 'A sensor that detects heat or motion, used on mine sites for fire detection, proximity warning systems on heavy equipment, and intruder detection in restricted areas.', 'Monitoring', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'inrush', 'en', 'Inrush', 'A sudden and uncontrolled entry of water, mud, or other material into a mine excavation. Inrushes can be catastrophic and are typically caused by breaching underground water bodies or saturated tailings.', 'Ground Hazards', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'inspector', 'en', 'Inspector', 'A government-appointed official with authority to enter and inspect mine sites to ensure compliance with mining regulations, safety standards, and environmental requirements.', 'Safety & Personnel', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'intrusive-rock', 'en', 'Intrusive Rock', 'Rock formed from magma that has intruded into existing formations and solidified underground. Intrusive bodies like granite and diorite are common hosts for many metal ore deposits.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'jsa', 'en', 'JSA', 'Job Safety Analysis — a systematic process for identifying hazards associated with a specific job or task before work begins, then determining appropriate controls to eliminate or minimize risk to workers. Mandatory before all high-risk tasks.', 'Safety Planning', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'jumbo-drill', 'en', 'Jumbo Drill', 'A self-propelled underground drilling machine with one or more drill arms (booms) used to drill blast holes in tunnel faces and development headings. The primary development tool in underground mines.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'kill-switch', 'en', 'Kill Switch', 'An emergency device that immediately cuts power to a machine or conveyor when activated. Must be clearly marked, easily accessible, and regularly tested to ensure it functions in an emergency.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'kiln', 'en', 'Kiln', 'A rotating furnace used to heat ore or concentrate at high temperatures to drive off moisture, oxidize sulfides, or prepare material for smelting. A key piece of equipment in many metallurgical operations.', 'Processing', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'leaching', 'en', 'Leaching', 'The process of dissolving valuable minerals from ore using chemical solutions (typically cyanide for gold or sulfuric acid for copper). Can be done in heaps, tanks, or in-situ.', 'Processing', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'lithology', 'en', 'Lithology', 'The physical characteristics of a rock, including its color, texture, mineral composition, and grain size. Accurate lithological logging of drill core is essential for geological interpretation and mine planning.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'load-and-haul', 'en', 'Load and Haul', 'The combined operations of loading broken ore or waste into trucks using excavators or loaders, and hauling it to the processing plant, waste dump, or stockpile.', 'Operations', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'loader', 'en', 'Loader', 'A wheeled or tracked machine with a front bucket used to load blasted material into haul trucks. Also called a front-end loader (FEL) or wheel loader.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'lode', 'en', 'Lode', 'A vein or seam of metal-bearing ore embedded within rock. Lode mining involves extracting ore from these veins, as contrasted with placer mining of alluvial deposits.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'loto', 'en', 'LOTO', 'Lockout/Tagout — a critical safety procedure ensuring that dangerous energy sources (electrical, hydraulic, pneumatic) are isolated and cannot be re-energized while maintenance or repair work is in progress. Failure to apply LOTO is a common cause of serious injuries.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'magazine', 'en', 'Magazine', 'A secure, purpose-built storage facility for explosives, detonators, and blasting accessories. Must be licensed, maintained to strict standards, and located a safe distance from workings and facilities.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'manway', 'en', 'Manway', 'A passage or ladder way in an underground mine used exclusively by workers for access and egress. Manways must be kept clear of obstruction and in safe condition at all times.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'methane', 'en', 'Methane', 'A flammable and explosive gas (CH4) naturally occurring in coal and some metalliferous mines. Methane accumulations must be detected early and diluted through ventilation to prevent explosions.', 'Ground Hazards', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'mill', 'en', 'Mill', 'A facility where blasted ore is crushed, ground, and processed to extract valuable minerals. Also refers to the grinding machines (ball mills, rod mills) within the facility.', 'Processing', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'mine-plan', 'en', 'Mine Plan', 'A comprehensive document specifying how a mine will be operated, including pit or underground design, production schedule, equipment requirements, and waste management strategies.', 'Operations', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'mine-rescue', 'en', 'Mine Rescue', 'A team of specially trained personnel equipped to respond to underground emergencies including fires, explosions, cave-ins, and flooding. All mines must have access to a mine rescue team.', 'Emergency Procedures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'misfired-shot', 'en', 'Misfired Shot', 'An explosive charge that has failed to detonate as intended during a blast. Misfires are extremely dangerous and must only be investigated and dealt with by a licensed shot-firer following strict procedures.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'monitoring', 'en', 'Monitoring', 'The continuous or periodic measurement and recording of safety-critical parameters such as slope movement, gas levels, water pressure, and structural integrity to detect early signs of hazardous conditions.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'motor-grader', 'en', 'Motor Grader', 'A machine with a long adjustable blade used to create flat surfaces and maintain haul roads on mine sites. Proper road grading reduces vehicle accidents and equipment damage.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'mucking', 'en', 'Mucking', 'The process of loading blasted or broken rock (muck) into trucks or other conveyances for transport. The term is commonly used in underground mining operations.', 'Operations', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'muster-point', 'en', 'Muster Point', 'A pre-designated, safe location where all workers must assemble in the event of an emergency evacuation. Must be clearly marked, well-known to all site personnel, and practiced regularly in drills.', 'Emergency Procedures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'near-miss', 'en', 'Near Miss', 'An unplanned event that did not result in injury, illness, or damage — but had the potential to do so. Near misses must be reported and investigated immediately to prevent future accidents.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'noise-induced-hearing-loss', 'en', 'Noise Induced Hearing Loss (NIHL)', 'Permanent hearing damage caused by prolonged exposure to high levels of noise in the workplace. Mining is one of the highest-risk industries for NIHL. Prevention requires hearing protection and engineering noise controls.', 'Health & Hygiene', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'open-pit', 'en', 'Open Pit', 'A type of surface mine in which rock or minerals are extracted from an open pit or borrow. Open pits are characterized by a series of descending benches and are suited to large, near-surface ore bodies.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'ore', 'en', 'Ore', 'Rock or mineral that contains enough of a valuable substance (metal, mineral, or gemstone) to make it economically worthwhile to mine and process at the current market price.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'ore-body', 'en', 'Ore Body', 'A mass of rock containing sufficient mineral content and extent to be economically mineable. Ore bodies can be tabular (flat), massive (large blob), or disseminated (spread throughout rock).', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'ore-pass', 'en', 'Ore Pass', 'A vertical or steeply inclined underground opening through which ore is dropped from an upper level to a lower level for collection and transport. Ore passes must be managed carefully to prevent blockages and hang-ups.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'ore-reserve', 'en', 'Ore Reserve', 'The portion of a mineral resource that has been assessed as economically and technically mineable under defined conditions. Used to determine mine life and financial value.', 'Operations', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'overburden', 'en', 'Overburden', 'Rock, soil, and other material that overlies an ore deposit and must be removed during open pit mining before the ore can be accessed. Overburden is disposed of in waste dumps.', 'Open Pit Mining', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'oxidation', 'en', 'Oxidation', 'A chemical process where minerals react with oxygen, often changing their properties. Oxidized ore near the surface can be easier to process than fresh sulfide ore deeper in a deposit.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'paste-fill', 'en', 'Paste Fill', 'A thick mixture of tailings, water, and binder (cement) used to fill underground voids. Paste fill provides structural support and reduces the volume of tailings requiring surface storage.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'permit-to-work', 'en', 'Permit to Work', 'A formal, written authorization required before commencing high-risk work such as confined space entry, hot work, working at heights, or electrical isolation. Ensures hazards are identified and controls are in place.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'pillar', 'en', 'Pillar', 'A block of unmined ore or rock left in place to support the roof and walls of underground excavations. Pillars must be sized correctly — premature extraction of pillars can cause catastrophic collapses.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'pit-dewatering', 'en', 'Pit Dewatering', 'The ongoing process of removing groundwater and surface water from an open pit mine to maintain safe and workable conditions. Includes pumps, sumps, drains, and water diversion channels.', 'Operations', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'pit-limit', 'en', 'Pit Limit', 'The boundary of an open pit mine, defined by the point at which the cost of mining exceeds the revenue from the ore. Pit limits are calculated using optimization software considering ore grade, commodity price, and costs.', 'Open Pit Mining', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'placer-mining', 'en', 'Placer Mining', 'The extraction of valuable minerals (typically gold, tin, or diamonds) from alluvial or placer deposits in riverbeds, beaches, or ancient water channels using washing and gravity separation.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'portal', 'en', 'Portal', 'The entrance to a horizontal or inclined underground mine opening such as an adit, decline, or tunnel. Portals must be secured with concrete headwalls to prevent collapse and clearly marked with safety signage.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'ppe', 'en', 'PPE', 'Personal Protective Equipment — any device, clothing, or equipment worn by a worker to minimize exposure to specific occupational hazards. In mining, mandatory PPE includes hard hat, safety boots, hi-vis vest, safety glasses, and gloves.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'pre-shift-inspection', 'en', 'Pre-Shift Inspection', 'A mandatory inspection of equipment and the work area performed by the operator before commencing each shift. Identifies defects, hazards, and unsafe conditions before work begins.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'priming', 'en', 'Priming', 'The process of inserting a detonator into a primer explosive to create an initiation assembly that will reliably detonate the main explosive charge in a blast hole.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'proximity-detection-system', 'en', 'Proximity Detection System', 'An electronic system that detects and alerts when a person enters the danger zone around operating heavy machinery, helping to prevent vehicle-pedestrian collisions — a leading cause of mine fatalities.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'pyritic-ore', 'en', 'Pyritic Ore', 'Ore containing significant amounts of iron sulfide (pyrite, FeS2). Pyritic ores can generate acid mine drainage when exposed to air and water, and may require special processing and environmental management.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'quarry', 'en', 'Quarry', 'A type of open-pit mine from which construction materials such as limestone, granite, sand, and gravel are extracted. Quarries use drilling and blasting similar to metalliferous mining.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'quartzite', 'en', 'Quartzite', 'A hard, metamorphic rock formed from sandstone. Quartzite is extremely abrasive and poses a significant silicosis risk when drilled or blasted, requiring respiratory protection and dust suppression.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'raise', 'en', 'Raise', 'A vertical or steeply inclined underground opening driven upward from one level to another. Raises are used for ventilation, ore passes, and access between levels.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'reclamation', 'en', 'Reclamation', 'The process of restoring a mined area to a stable, safe, and productive state after mining operations cease. Includes recontouring, revegetation, water management, and ongoing monitoring.', 'Environment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'resource', 'en', 'Resource', 'An estimate of the quantity and grade of mineralization in a deposit, classified into Inferred, Indicated, and Measured categories based on the level of geological confidence.', 'Exploration', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'rib', 'en', 'Rib', 'The side wall of an underground excavation such as a drive, drift, or tunnel. Ribs are subject to ground pressure and must be scaled and supported to prevent falls of ground.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'risk', 'en', 'Risk', 'The combination of the likelihood that a hazard will cause harm and the severity of that harm. Risk = Likelihood × Consequence. Risk management involves reducing one or both of these factors.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'risk-assessment', 'en', 'Risk Assessment', 'The systematic process of identifying hazards, evaluating the likelihood and consequence of harm, and determining appropriate control measures to reduce risk to an acceptable level.', 'Safety Planning', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'rock-bolt', 'en', 'Rock Bolt', 'A steel bolt installed into drilled holes in rock to reinforce and stabilize the surrounding rock mass. Rock bolts are the most widely used form of ground support in underground mining.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'rock-burst', 'en', 'Rock Burst', 'A sudden, violent failure of rock in a highly stressed underground environment, causing rock to be explosively ejected from walls or roof. A major hazard in deep underground mines.', 'Ground Hazards', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'rock-mechanics', 'en', 'Rock Mechanics', 'The science of how rock behaves under applied loads and stresses. Rock mechanics principles underpin the design of underground excavations, pit slopes, and all ground support systems.', 'Engineering', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'rom', 'en', 'ROM', 'Run of Mine — ore as it comes directly from the mining face, before any processing or sorting. ROM material is transported to a stockpile or directly to the crusher at the processing plant.', 'Grade Control', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'roof-bolt', 'en', 'Roof Bolt', 'A rock bolt installed in the roof (back) of an underground excavation to bind and stabilize overhead rock layers. Roof bolting is essential in all underground mines to prevent falls of ground.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'safety-data-sheet', 'en', 'Safety Data Sheet (SDS)', 'A standardized document providing detailed information about a hazardous substance including its physical and health hazards, safe handling, storage, disposal, and emergency procedures. Formerly known as MSDS.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'safety-officer', 'en', 'Safety Officer', 'A trained professional responsible for developing, implementing, and monitoring safety systems on a mine site. The safety officer has the authority to stop unsafe work and must be consulted before high-risk tasks.', 'Safety & Personnel', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'scaling', 'en', 'Scaling', 'The manual or mechanical removal of loose, cracked, or unstable rock from mine faces, walls, and ceilings before work commences in that area. Performed using a scaling bar or mechanical scaler.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'seismic-monitoring', 'en', 'Seismic Monitoring', 'The continuous measurement of ground vibrations using seismographs to detect and monitor underground rock movements, blasting effects, and potential slope instability or rockburst activity.', 'Monitoring', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'shaft', 'en', 'Shaft', 'A vertical or near-vertical underground opening used for access, ventilation, ore hoisting, and services in an underground mine. Shafts can reach depths of several kilometres in deep mines.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'shotcrete', 'en', 'Shotcrete', 'Concrete sprayed at high pressure onto rock surfaces to provide structural support and prevent deterioration of excavation walls and roof. Widely used in underground development and rehabilitation.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'shot-firer', 'en', 'Shot-Firer', 'A person who holds a license to handle, prepare, and detonate explosives on a mine site. Shot-firers are responsible for the safe execution of all blasting operations and management of misfires.', 'Safety & Personnel', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'silica', 'en', 'Silica', 'Silicon dioxide (SiO2) — a mineral found in most rock types. Inhalation of fine silica dust causes silicosis, a serious, irreversible, and potentially fatal lung disease. Silica dust is the number one occupational health hazard in mining.', 'Health & Hygiene', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'silicosis', 'en', 'Silicosis', 'A progressive, incurable, and potentially fatal occupational lung disease caused by the inhalation of fine crystalline silica dust over time. Prevention requires dust control, respiratory PPE, and regular health monitoring.', 'Health & Hygiene', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'sill-pillar', 'en', 'Sill Pillar', 'A horizontal pillar of unmined ore left between stoping levels to provide roof support for lower workings. Sill pillar recovery is one of the highest-risk activities in underground mining.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'skip', 'en', 'Skip', 'A large bucket or container used to hoist ore and waste rock from underground to surface in a mine shaft. Skips are counterbalanced and guided by the shaft structure.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'slope-monitoring', 'en', 'Slope Monitoring', 'The ongoing measurement of pit wall and dump face movement to detect early signs of instability. Methods include survey prisms, radar, inclinometers, and GPS systems.', 'Monitoring', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'slope-stability', 'en', 'Slope Stability', 'The ability of a pit wall, underground excavation, or waste dump face to remain in place without failing. Depends on rock strength, geological structure, slope angle, water pressure, and blasting effects.', 'Geotechnical', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'slurry', 'en', 'Slurry', 'A semi-fluid mixture of finely ground solid particles and water, commonly found in mineral processing circuits. Slurry pipelines transport processed ore between facilities.', 'Processing', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'smelting', 'en', 'Smelting', 'The process of extracting metal from ore by heating it to high temperatures in a furnace, causing chemical reduction and separation of the metal from impurities (slag).', 'Processing', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'spoil', 'en', 'Spoil', 'Overburden, waste rock, or other material removed during mining that has no economic value. Spoil must be disposed of in designated waste dumps engineered for long-term stability.', 'Waste Management', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'spontaneous-combustion', 'en', 'Spontaneous Combustion', 'The self-ignition of coal or sulfide-bearing waste rock when exposed to air without an external ignition source. Spontaneous combustion fires in waste dumps and coal mines are difficult to extinguish and can release toxic gases.', 'Ground Hazards', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'stemming', 'en', 'Stemming', 'Inert material (usually drill cuttings or crushed rock) placed in the top portion of a blast hole above the explosive charge to contain blast energy and reduce flyrock and airblast.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'stockpile', 'en', 'Stockpile', 'A designated area where ore, waste rock, or low-grade material is temporarily stored before processing, treatment, or permanent disposal. Stockpile management includes grade tracking and stability monitoring.', 'Operations', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'stope', 'en', 'Stope', 'The underground excavation from which ore is extracted after development. Stopes are the primary production areas in an underground mine and require careful ground support design.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'strike', 'en', 'Strike', 'The horizontal direction of a rock layer, fault, or ore body, measured relative to north. Understanding the strike of an ore body is fundamental to mine planning and underground development.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'strip-ratio', 'en', 'Strip Ratio', 'The ratio of waste material (overburden) to ore that must be mined. A strip ratio of 5:1 means 5 tonnes of waste are moved for every tonne of ore. Higher strip ratios increase mining costs.', 'Open Pit Mining', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'sub-level-caving', 'en', 'Sub-Level Caving', 'An underground mining method where ore is drilled and blasted from sublevels and allowed to cave and flow to drawpoints below. A low-cost, high-production method suited to large ore bodies.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'subsidence', 'en', 'Subsidence', 'The sinking or settlement of the ground surface above an underground mine caused by the collapse or closure of underground voids. Surface subsidence can damage infrastructure, roads, and buildings.', 'Ground Hazards', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'sump', 'en', 'Sump', 'A pit or low point in an underground mine where water collects for pumping to surface. Sumps must be maintained and pumped regularly to prevent flooding of working areas.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'surety-bond', 'en', 'Surety Bond', 'A financial bond posted by a mining company to guarantee that it will fulfill environmental obligations including rehabilitation and closure when mining operations cease.', 'Environment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'tailings', 'en', 'Tailings', 'Finely ground rock and processing waste remaining after valuable minerals have been extracted from ore. Tailings contain residual chemicals and must be stored in engineered Tailings Storage Facilities (TSFs).', 'Waste Management', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'tailings-storage-facility', 'en', 'Tailings Storage Facility (TSF)', 'An engineered structure used to contain tailings from mineral processing. TSF failures can be catastrophic — causing loss of life and severe environmental damage. Requires constant monitoring and expert management.', 'Waste Management', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'tbm', 'en', 'TBM', 'Tunnel Boring Machine — a large mechanical device used to excavate tunnels by grinding away rock with a rotating cutting head. TBMs produce smoother tunnels with less ground disturbance than drill-and-blast methods.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'tonne', 'en', 'Tonne', 'The standard unit of mass used in mining, equal to 1,000 kilograms (2,205 pounds). Ore grades are typically expressed in grams per tonne (g/t), and production in tonnes per day (t/d) or per year (t/a).', 'Operations', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'toolbox-talk', 'en', 'Toolbox Talk', 'A short, informal safety meeting held before a work shift or specific task to discuss hazards, safety procedures, and the work plan. Attendance is mandatory for all workers and must be documented.', 'Safety Planning', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'topography', 'en', 'Topography', 'The natural shape and features of the land surface, including hills, valleys, and drainage patterns. Topographic maps and surveys are essential for mine design, haul road planning, and water management.', 'Engineering', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'tramp-metal', 'en', 'Tramp Metal', 'Pieces of metal such as broken drill steel, teeth from buckets, and cable fragments that find their way into the ore stream and can damage crushing and grinding equipment in the processing plant.', 'Operations', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'tunnel', 'en', 'Tunnel', 'A horizontal underground passage connecting two surface openings. Tunnels are driven for access, exploration, and transport in both surface and underground mining operations.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'underground-mining', 'en', 'Underground Mining', 'Mining conducted below the earth''s surface, accessed via shafts, declines, or adits. Used when ore bodies are too deep for open pit mining. Underground mining poses unique hazards including falls of ground, fire, and poor ventilation.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'uniaxial-compressive-strength', 'en', 'Uniaxial Compressive Strength (UCS)', 'A laboratory measurement of the maximum stress a cylindrical rock sample can withstand under axial loading before failure. UCS is a fundamental input for underground support design and slope stability analysis.', 'Engineering', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'upcast-shaft', 'en', 'Upcast Shaft', 'A mine shaft through which contaminated, heated air is drawn up and out of the underground workings by fans. The upcast shaft is a critical component of the mine ventilation system.', 'Ventilation', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'ventilation', 'en', 'Ventilation', 'The system of fans, shafts, raises, and ducts used to supply fresh air to underground workings and remove contaminated air, heat, dust, and blasting fumes. Inadequate ventilation is one of the most serious underground hazards.', 'Ventilation', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'void', 'en', 'Void', 'An empty underground space created by mining. Voids must be properly supported, backfilled, or fenced off to prevent collapse, surface subsidence, or accidental entry by workers.', 'Ground Hazards', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'void-ratio', 'en', 'Void Ratio', 'The ratio of the volume of voids (pores and spaces) to the volume of solid material in rock or soil. High void ratios indicate looser, potentially less stable ground conditions.', 'Geotechnical', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'waste-rock', 'en', 'Waste Rock', 'Rock that is excavated during mining but contains insufficient mineral content to be economically processed. Waste rock is permanently disposed of in engineered waste dumps.', 'Waste Management', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'water-table', 'en', 'Water Table', 'The level below the earth''s surface at which the ground is saturated with water. Mining below the water table requires dewatering and can affect local groundwater supplies.', 'Hydrology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'weathering', 'en', 'Weathering', 'The physical and chemical breakdown of rock at or near the earth''s surface by exposure to weather, water, and biological processes. Weathered rock is generally weaker and more prone to slope instability.', 'Geology', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'working-face', 'en', 'Working Face', 'The area of the mine where active excavation, drilling, or blasting is currently taking place. This is typically the highest-risk area on a mine site requiring the most stringent hazard controls.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'working-place', 'en', 'Working Place', 'The specific location where an individual miner or crew is working at any given time. Each working place must be inspected for hazards before work commences at the start of every shift.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'xrf-analyzer', 'en', 'XRF Analyzer', 'X-Ray Fluorescence analyzer — a portable handheld device used to rapidly determine the elemental composition and grade of rock or ore samples on site without laboratory processing.', 'Testing & Analysis', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'anchor-bolt', 'en', 'Anchor Bolt', 'A steel bolt grouted or mechanically anchored deep into rock to tie back unstable rock masses and reinforce pit walls or underground excavations against movement.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'autonomous-equipment', 'en', 'Autonomous Equipment', 'Mining equipment such as haul trucks and drills that operate without a human driver, controlled by onboard computers and remote monitoring systems. Reduces worker exposure to hazardous areas but requires strict exclusion zone management.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'ball-mill', 'en', 'Ball Mill', 'A large steel drum partly filled with steel balls that rotates to grind ore into fine particles for mineral processing. Ball mills are one of the most energy-intensive pieces of equipment in a processing plant.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'bentonite', 'en', 'Bentonite', 'A highly absorbent clay mineral used as a drilling fluid additive to seal borehole walls, lubricate drill bits, and carry drill cuttings to the surface during exploration drilling.', 'Exploration', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'blasthole-logging', 'en', 'Blasthole Logging', 'The systematic sampling and recording of drill chips from blast holes to determine ore grade before blasting. Blasthole logging is a critical grade control tool in open pit operations.', 'Grade Control', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'cable-bolt', 'en', 'Cable Bolt', 'A flexible steel cable grouted into a long borehole to reinforce and stitch together large volumes of rock mass, providing support in areas of high stress or complex geology.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'carbon-monoxide', 'en', 'Carbon Monoxide (CO)', 'A colourless, odourless, and highly toxic gas produced by incomplete combustion of fuel and by blasting. CO cannot be detected by smell — gas detectors are essential in all underground environments.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'catchment-pond', 'en', 'Catchment Pond', 'An engineered pond designed to collect and contain runoff water from mine site areas, preventing contaminated water from flowing into natural water courses.', 'Environment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'controlled-blasting', 'en', 'Controlled Blasting', 'Blasting techniques such as pre-splitting and trim blasting used near final pit walls to minimize rock damage and produce a stable, clean slope face.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'conveyor-belt', 'en', 'Conveyor Belt', 'A continuous moving belt system used to transport ore, crushed rock, or waste over long distances on surface or underground. Must be fitted with emergency stop pulls, guards, and belt alignment switches.', 'Mining Equipment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'downcast-shaft', 'en', 'Downcast Shaft', 'A mine shaft through which fresh air is drawn down into underground workings. The downcast shaft is the inlet side of the underground ventilation circuit.', 'Ventilation', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'draw-point', 'en', 'Draw Point', 'The opening at the base of a stope or caving block through which broken ore flows under gravity for loading and transport. Draw point management is critical to ore recovery and dilution control.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'drill-and-blast', 'en', 'Drill and Blast', 'The most widely used method of rock excavation in mining, involving drilling holes into rock, loading them with explosives, and blasting to fragment the rock for loading and hauling.', 'Drilling & Blasting', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'electrostatic-precipitator', 'en', 'Electrostatic Precipitator', 'An air pollution control device that uses electrical charges to remove fine dust and particulate matter from exhaust gases in processing plants and smelters.', 'Environment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'emergency-eyewash-station', 'en', 'Emergency Eyewash Station', 'A dedicated water station designed to flush chemicals from the eyes in the event of a splash injury. Must be located within 10 seconds travel of any area where eye hazards exist and tested weekly.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'environmental-impact-assessment', 'en', 'Environmental Impact Assessment (EIA)', 'A formal study assessing the potential environmental effects of a mining project before it commences, including impacts on water, air, soil, biodiversity, and local communities.', 'Environment', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'explosive-limit', 'en', 'Explosive Limit', 'The concentration range of a flammable gas in air within which it can ignite and explode. Below the Lower Explosive Limit (LEL) or above the Upper Explosive Limit (UEL) the gas will not ignite.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'fire-triangle', 'en', 'Fire Triangle', 'The three elements required for fire: fuel, heat, and oxygen. Removing any one element extinguishes the fire. Understanding the fire triangle is fundamental to fire prevention and suppression on mine sites.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'free-cyanide', 'en', 'Free Cyanide', 'The dissolved cyanide fraction in a processing solution that is available to react with and dissolve gold. Free cyanide levels in tailings must be managed and monitored to protect the environment.', 'Processing', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'geomechanics', 'en', 'Geomechanics', 'The study of the mechanical behavior of geological materials — rock and soil — under applied forces. Geomechanics principles govern the design of all mine excavations, support systems, and slopes.', 'Engineering', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'gravity-recovery', 'en', 'Gravity Recovery', 'A mineral processing method that separates valuable minerals from waste based on differences in specific gravity (density). Widely used for gold, tin, and diamond recovery.', 'Processing', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'heat-stress', 'en', 'Heat Stress', 'A serious health risk caused by prolonged exposure to high temperatures and humidity in underground or open pit environments. Symptoms include dizziness, nausea, and loss of consciousness. Can be fatal if untreated.', 'Health & Hygiene', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'highwall-mining', 'en', 'Highwall Mining', 'A surface mining technique that uses a remotely controlled cutting machine to extract coal or minerals from exposed highwall faces without requiring workers to enter the highwall area.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'in-situ-leaching', 'en', 'In-Situ Leaching', 'A mining technique where a leaching solution is injected directly into an ore body underground to dissolve minerals, which are then pumped to the surface for recovery — without physical excavation.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'instrumentation', 'en', 'Instrumentation', 'The collection of sensors, gauges, and monitoring devices installed throughout a mine to measure and record conditions such as ground movement, water pressure, gas levels, and equipment performance.', 'Monitoring', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'level', 'en', 'Level', 'A horizontal underground working connected to a shaft or decline at a specific depth. Levels provide access for development, production, and services and are typically spaced 20–60 metres apart vertically.', 'Mining Structures', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'long-hole-stoping', 'en', 'Long Hole Stoping', 'An underground mining method where long blast holes are drilled upward or downward to blast large volumes of ore in a single blast. A productive and cost-effective method for large, well-defined ore bodies.', 'Mining Methods', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'material-safety-data-sheet', 'en', 'Material Safety Data Sheet (MSDS)', 'The predecessor to the modern Safety Data Sheet (SDS). Contains information about the hazards, handling, and emergency response for a chemical substance. The term MSDS is still commonly used on older mine sites.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'mesh-wire-mesh', 'en', 'Mesh / Wire Mesh', 'Steel wire mesh panels pinned to the rock surface with rock bolts to hold loose rock fragments in place and prevent minor falls of ground in underground excavations.', 'Ground Support', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'zero-harm', 'en', 'Zero Harm', 'The philosophy and goal of achieving zero workplace injuries, illnesses, and fatalities on a mine site. Zero Harm is the foundation of modern mine safety culture and requires active commitment from all personnel.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;
insert into public.public_content (kind, slug, language, title, body, category, status, source)
values ('glossary_term', 'zone-of-influence', 'en', 'Zone of Influence', 'The area around a blast, excavation, or heavy machinery operation that may be affected by its activity. All personnel and equipment must be cleared from the zone of influence before blasting or major earthworks commence.', 'Mine Safety', 'draft', 'MineGuard field app reference content (data.js); no qualified sign-off recorded')
on conflict (kind, slug, language, version) do nothing;

-- one provenance event per imported draft
insert into public.public_content_events (content_id, action, to_status, actor_id, note)
select c.id, 'import', 'draft', null, 'Imported as a draft from the MineGuard field app reference content; not reviewed.'
  from public.public_content c
 where c.kind = 'glossary_term' and c.version = 1 and c.status = 'draft' and c.author_id is null
   and not exists (select 1 from public.public_content_events e where e.content_id = c.id);

commit;
